findings.codeql_raw_query:
/**
 * @name Arbitrary file write during archive extraction ("Zip Slip")
 * @description Extracting files from a malicious archive without validating the destination path can allow an attacker to overwrite arbitrary files.
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs
import semmle.python.Concepts

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: Filenames from ZipFile or TarFile
    exists(DataFlow::CallCfgNode call |
      // zipfile.ZipFile().namelist() returning list of strings
      (
        call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember("namelist").getACall() and
        source = call
      )
      or
      // zipfile.ZipInfo.filename
      (
         // This is harder to model precisely with API graphs for attributes of objects in a list, 
         // but let's try getting members of ZipFile.infolist()
         // simplified: look for iteration over .namelist() or .infolist()
         exists(DataFlow::CallCfgNode listCall | 
            listCall = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["namelist", "infolist"]).getACall()
            and
            // For now, let's just consider the call itself a source of tainted data (the list)
            // TaintTracking should handle flow from list to element? CodeQL's default taint tracking usually handles list iteration.
            source = listCall
         )
      )
      or
      // tarfile.TarFile().getnames() or .getmembers()
      (
        call = API::moduleImport("tarfile").getMember("TarFile").getReturn().getMember(["getnames", "getmembers"]).getACall() and
        source = call
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: File system access using the path
    sink = any(FileSystemAccess fa).getAPathArgument()
  }

  predicate isBarrier(DataFlow::Node node) {
    // Barrier: os.path.abspath, os.path.realpath used in a check? 
    // This is hard to model as a simple barrier node unless we see a check.
    // However, explicit sanitization often involves abspath/realpath.
    // If the path flows through abspath, it's not necessarily safe, but if it's then checked...
    // Let's rely on default barriers or lack thereof. 
    // Ideally we want to find flow that does NOT go through a check.
    none()
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential Zip Slip: file extraction using unsanitized path from $@.", source.getNode(), "archive member"
